#!/usr/bin/env bash
# Checks one evaluation task of the agent guides (docs/agent-guidance.md)
# in a project generated by scripts/check-template.sh, after an agent, a
# person or --solution did the task in it:
#
#   - the project's own tests pass, and it has more of them than the
#     template came with
#   - acceptance/<task>.rs passes against it
#   - it builds with and without local mode
#   - with --run: the server starts and answers the task's requests over
#     REST as the task says (embedded Postgres, as in the quickstart)
#
# --solution applies solutions/<task>.patch first and takes it out again
# afterwards. CI does that for every task (check-solutions.sh), so a guide, the template and the
# API can't drift apart unnoticed: a reference solution that stops
# compiling or passing fails the build.
#
# Usage: scripts/agent-guides/eval/check.sh <task> <project-dir> [--solution] [--run]
#        <task>: add-command | evolve-event | sensitive-field
set -euo pipefail

here="$(cd "$(dirname "$0")" && pwd)"
root="$(cd "$here/../../.." && pwd)"

task="${1:-}"
app="${2:-}"
solution=false
run=false
shift 2 || { echo 'eval-check: usage: check.sh <task> <project-dir> [--solution] [--run]' >&2; exit 2; }
while [[ $# -gt 0 ]]; do
    case "$1" in
        --solution) solution=true ;;
        --run) run=true ;;
        *) echo "eval-check: unknown argument $1" >&2; exit 2 ;;
    esac
    shift
done
[[ -f "$here/tasks/$task.md" ]] || { echo "eval-check: no task '$task'" >&2; exit 2; }
[[ -f "$app/Cargo.toml" ]] || { echo "eval-check: $app is not a project" >&2; exit 2; }
app="$(cd "$app" && pwd)"

work="$(mktemp -d)"
server_pid=
cleanup() {
    if [[ -n "$server_pid" ]] && kill -0 "$server_pid" 2>/dev/null; then
        kill -INT "$server_pid" 2>/dev/null || true
        sleep 5
        kill -KILL "$server_pid" 2>/dev/null || true
    fi
    rm -f "$app/tests/acceptance.rs"
    if $solution && [[ -d "$work/src" ]]; then
        rm -rf "$app/src" "$app/tests"
        cp -r "$work/src" "$work/tests" "$app/"
    fi
    rm -rf "$work"
}
trap cleanup EXIT

fail() {
    echo "eval-check: $task: $*" >&2
    exit 1
}

cd "$app"
if $solution; then
    cp -r src tests "$work/"
    patch -p1 --quiet < "$here/solutions/$task.patch" ||
        fail "the reference solution no longer applies to the template: redo it and record the patch"
fi

# Tests of the project's own, counted before the acceptance tests join them.
before="$(cat "$root"/templates/skilj-template/tests/*.rs | grep -c '#\[test\]')"
after="$(cat tests/*.rs | grep -c '#\[test\]')"
[[ "$after" -gt "$before" ]] || fail "no test was added: the template has $before, the project $after"

cp "$here/acceptance/$task.rs" tests/acceptance.rs
env -u DATABASE_URL cargo test --no-default-features
cargo check --all-targets
cargo check --all-targets --no-default-features

case "$task" in
    sensitive-field)
        # Without a key provider, a write with a sensitive field is refused
        # (encryption_master_key_not_configured).
        grep -rq 'key_provider' src || fail "no key provider is configured, so the server can't store the email"
        ;;
esac

if ! $run; then
    echo "eval-check: $task: OK (not run). Review it by hand as docs/agent-guidance.md lists."
    exit 0
fi

# target/ of the project, or CARGO_TARGET_DIR.
target="$(cargo metadata --format-version 1 --no-deps | grep -oE '"target_directory":"[^"]*"' | cut -d'"' -f4)"
cargo build --bin server
port="$(python3 -c 'import socket; s = socket.socket(); s.bind(("127.0.0.1", 0)); print(s.getsockname()[1])')"
log="$work/server.log"
env -u DATABASE_URL PORT="$port" SKILJ_LOCAL_DATA_DIR="$work/postgres" "$target/debug/server" >"$log" 2>&1 &
server_pid=$!
for _ in $(seq 1 300); do
    grep -q '^listening on ' "$log" && break
    kill -0 "$server_pid" 2>/dev/null || { cat "$log" >&2; fail "the server exited before it was ready"; }
    sleep 1
done
grep -q '^listening on ' "$log" || { cat "$log" >&2; fail "the server wasn't ready within 300s"; }

# trigger <command type> <payload> <what the answer must contain>
trigger() {
    local token answer
    token="$(grep -oE "^  wallet/$1: [^ ]+" "$log" | awk '{print $2}')"
    [[ -n "$token" ]] || { cat "$log" >&2; fail "the server printed no token for $1"; }
    answer="$(curl -sS "localhost:$port/v1/commands/trigger" -H "authorization: Bearer $token" \
        -H 'content-type: application/json' -d "{\"payload\":$2}")"
    [[ "$answer" == *"$3"* ]] || { cat "$log" >&2; fail "$1 $2 answered $answer, expected $3"; }
}

accepted='"accepted":true'
rejected() { echo "\"rejectionKind\":\"$1\""; }
case "$task" in
    add-command)
        trigger Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
        trigger CloseWallet '{"wallet_id":"w1"}' "$(rejected wallet_not_empty)"
        trigger Withdraw '{"wallet_id":"w1","amount":100}' "$accepted"
        trigger CloseWallet '{"wallet_id":"w1"}' "$accepted"
        # Read back from the store: these fail when WalletClosed isn't
        # decoded, or isn't tagged with the wallet.
        trigger Deposit '{"wallet_id":"w1","amount":1}' "$(rejected wallet_closed)"
        trigger CloseWallet '{"wallet_id":"w1"}' "$(rejected wallet_closed)"
        trigger Deposit '{"wallet_id":"w2","amount":1}' "$accepted"
        ;;
    evolve-event)
        trigger Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
        trigger Deposit '{"wallet_id":"w1","amount":50,"reference":"rent"}' "$accepted"
        # Both deposits read back, with and without a reference.
        trigger Withdraw '{"wallet_id":"w1","amount":150}' "$accepted"
        ;;
    sensitive-field)
        trigger RegisterOwner '{"wallet_id":"w1","owner_id":"o-1","email":"ada@example.com"}' "$accepted"
        # Read back and decrypted for decide().
        trigger RegisterOwner '{"wallet_id":"w1","owner_id":"o-2","email":"grace@example.com"}' \
            "$(rejected owner_already_registered)"
        trigger Deposit '{"wallet_id":"w1","amount":100}' "$accepted"
        trigger Withdraw '{"wallet_id":"w1","amount":100}' "$accepted"
        ;;
esac

kill -INT "$server_pid"
for _ in $(seq 1 30); do
    kill -0 "$server_pid" 2>/dev/null || break
    sleep 1
done
kill -0 "$server_pid" 2>/dev/null && fail "the server didn't stop within 30s of Ctrl-C"
wait "$server_pid" || fail "the server exited with a failure on Ctrl-C"
server_pid=

echo "eval-check: $task: OK (ran). Review it by hand as docs/agent-guidance.md lists."
